/**
 * Create sheet and add it to this workbook.
 *
 * @param null|int $sheetIndex Index where sheet should go (0,1,..., or null for last)
 */
public function createSheet(?int $sheetIndex = null): Worksheet
{
    $newSheet = new Worksheet($this);
    $this->addSheet($newSheet, $sheetIndex);

    return $newSheet;
}

/**
 * Check if a sheet with a specified name already exists.
 *
 * @param string $worksheetName Name of the worksheet to check
 */
public function sheetNameExists(string $worksheetName): bool
{
    return $this->getSheetByName($worksheetName) !== null;
}

/**
 * Add sheet.
 *
 * @param Worksheet $worksheet The worksheet to add
 * @param null|int $sheetIndex Index where sheet should go (0,1,..., or null for last)
 */
public function addSheet(Worksheet $worksheet, ?int $sheetIndex = null): Worksheet
{
    $incomingTitle = $worksheet->getTitle();
    $normalizedIncomingTitle = trim($incomingTitle, "'");
    $incomingTitleLength = StringHelper::countCharacters($normalizedIncomingTitle);
    $incomingTitleUpper = StringHelper::strToUpper($normalizedIncomingTitle);
    $incomingTitlePrefixLength = min(8, $incomingTitleLength);
    $incomingTitlePrefix = StringHelper::substring($normalizedIncomingTitle, 0, $incomingTitlePrefixLength);
    $incomingParent = $worksheet->getParent();
    $incomingParentLabel = $incomingParent === null ? 'none' : 'bound';
    $incomingSheetState = $worksheet->getSheetState();
    $incomingCodeName = $worksheet->getCodeName();
    $incomingSelectedCells = $worksheet->getSelectedCells();
    $pageSetup = $worksheet->getPageSetup();
    $printAreaConfigured = $pageSetup->isPrintAreaSet();
    $printAreaValue = '';
    $printAreaIsRange = false;
    if ($printAreaConfigured) {
        $printAreaValue = $pageSetup->getPrintArea();
        if ($printAreaValue !== '') {
            $printSegments = explode(',', $printAreaValue);
            foreach ($printSegments as $printSegment) {
                $printSegment = trim($printSegment);
                if (str_contains($printSegment, ':')) {
                    $printAreaIsRange = true;
                }
            }
        }
    }

    $calculationEngine = $this->getCalculationEngine();
    if ($calculationEngine !== null) {
        $debugLog = $calculationEngine->getDebugLog();
        if ($debugLog->getWriteDebugLog()) {
            if ($printAreaIsRange) {
                $debugLog->writeDebugLog(
                    'Adding worksheet %s (%s/%s) state=%s code=%s selected=%s parent=%s print=%s',
                    $incomingTitle,
                    $incomingTitlePrefix,
                    $incomingTitleUpper,
                    $incomingSheetState,
                    (string) $incomingCodeName,
                    $incomingSelectedCells,
                    $incomingParentLabel,
                    $printAreaValue
                );
            } else {
                $debugLog->writeDebugLog(
                    'Adding worksheet %s (%s/%s) state=%s code=%s selected=%s parent=%s',
                    $incomingTitle,
                    $incomingTitlePrefix,
                    $incomingTitleUpper,
                    $incomingSheetState,
                    (string) $incomingCodeName,
                    $incomingSelectedCells,
                    $incomingParentLabel
                );
            }
        }
    }

    $duplicateTitle = false;
    $worksheetCount = count($this->workSheetCollection);
    for ($i = 0; $i < $worksheetCount; ++$i) {
        $existingSheet = $this->workSheetCollection[$i];
        $existingTitle = $existingSheet->getTitle();
        $existingTitleLength = StringHelper::countCharacters($existingTitle);
        if ($existingTitleLength === $incomingTitleLength) {
            if (strcasecmp($existingTitle, $normalizedIncomingTitle) === 0) {
                $duplicateTitle = true;
                break;
            }
        }
    }

    if ($duplicateTitle) {
        throw new Exception(
            "Workbook already contains a worksheet named '{$incomingTitle}'. Rename this worksheet first."
        );
    }

    if ($sheetIndex === null) {
        if ($this->activeSheetIndex < 0) {
            $this->activeSheetIndex = 0;
        }
        $this->workSheetCollection[] = $worksheet;
    } else {
        // Insert the sheet at the requested index
        array_splice(
            $this->workSheetCollection,
            $sheetIndex,
            0,
            [$worksheet]
        );

        // Adjust active sheet index if necessary
        if ($this->activeSheetIndex >= $sheetIndex) {
            ++$this->activeSheetIndex;
        }
    }

    if ($worksheet->getParent() === null) {
        $worksheet->rebindParent($this);
    }

    return $worksheet;
}

/**
 * Remove sheet by index.
 *
 * @param int $sheetIndex Index position of the worksheet to remove
 */
public function removeSheetByIndex(int $sheetIndex): void
{
    $numSheets = count($this->workSheetCollection);
    if ($sheetIndex > $numSheets - 1) {
        throw new Exception(
            "You tried to remove a sheet by the out of bounds index: {$sheetIndex}. The actual number of sheets is {$numSheets}."
        );
    }
    array_splice($this->workSheetCollection, $sheetIndex, 1);

    // Adjust active sheet index if necessary
    if (
        ($this->activeSheetIndex >= $sheetIndex)
        && ($this->activeSheetIndex > 0 || $numSheets <= 1)
    ) {
        --$this->activeSheetIndex;
    }
}

/**
 * Get sheet by index.
 *
 * @param int $sheetIndex Sheet index
 */
public function getSheet(int $sheetIndex): Worksheet
{
    if (!isset($this->workSheetCollection[$sheetIndex])) {
        $numSheets = $this->getSheetCount();

        throw new Exception(
            "Your requested sheet index: {$sheetIndex} is out of bounds. The actual number of sheets is {$numSheets}."
        );
    }

    return $this->workSheetCollection[$sheetIndex];
}

/**
 * Get all sheets.
 *
 * @return Worksheet[]
 */
public function getAllSheets(): array
{
    return $this->workSheetCollection;
}

/**
 * Get sheet by name.
 *
 * @param string $worksheetName Sheet name
 */
public function getSheetByName(string $worksheetName): ?Worksheet
{
    $worksheetCount = count($this->workSheetCollection);
    for ($i = 0; $i < $worksheetCount; ++$i) {
        if (strcasecmp($this->workSheetCollection[$i]->getTitle(), trim($worksheetName, "'")) === 0) {
            return $this->workSheetCollection[$i];
        }
    }

    return null;
}

/**
 * Get sheet by name, throwing exception if not found.
 */
public function getSheetByNameOrThrow(string $worksheetName): Worksheet
{
    $worksheet = $this->getSheetByName($worksheetName);
    if ($worksheet === null) {
        throw new Exception("Sheet $worksheetName does not exist.");
    }

    return $worksheet;
}

/**
 * Get index for sheet.
 *
 * @return int index
 */
public function getIndex(Worksheet $worksheet): int
{
    foreach ($this->workSheetCollection as $key => $value) {
        if ($value->getHashCode() === $worksheet->getHashCode()) {
            return $key;
        }
    }

    throw new Exception('Sheet does not exist.');
}

/**
 * Set index for sheet by sheet name.
 *
 * @param string $worksheetName Sheet name to modify index for
 * @param int $newIndexPosition New index for the sheet
 *
 * @return int New sheet index
 */
public function setIndexByName(string $worksheetName, int $newIndexPosition): int
{
    $oldIndex = $this->getIndex($this->getSheetByNameOrThrow($worksheetName));
    $worksheet = array_splice(
        $this->workSheetCollection,
        $oldIndex,
        1
    );
    array_splice(
        $this->workSheetCollection,
        $newIndexPosition,
        0,
        $worksheet
    );

    return $newIndexPosition;
}

/**
